input.command:
cat > rulesets/production-default-branch-pr-review.json <<'E'
{
  "name": "production-default-branch-pr-review",
  "target": "branch",
  "enforcement": "active",
  "conditions": {
    "ref_name": { "include": ["~DEFAULT_BRANCH"], "exclude": [] },
    "repository_property": {
      "include": [ { "name": "tier", "property_values": ["production"] } ],
      "exclude": []
    }
  },
  "rules": [
    {
      "type": "pull_request",
      "parameters": {
        "required_approving_review_count": 1,
        "dismiss_stale_reviews_on_push": true,
        "require_code_owner_review": false,
        "require_last_push_approval": false,
        "required_review_thread_resolution": false
      }
    }
  ]
}
E
gh api -X POST orgs/northwind/rulesets --input rulesets/production-default-branch-pr-review.json --jq '{id,name,enforcement}'

